<?php
require_once '../config/db.php'; require_once '../includes/auth.php'; requireAdmin();
$id=(int)($_GET['id'] ?? 0);
$stmt=$pdo->prepare('SELECT id, username, email, role, created_at FROM users WHERE id=? LIMIT 1'); $stmt->execute([$id]); $user=$stmt->fetch();
if(!$user){ redirectTo('users.php'); }
$stmt=$pdo->prepare('SELECT b.*, c.name AS car_name FROM bookings b JOIN cars c ON b.car_id=c.id WHERE b.user_id=? ORDER BY b.created_at DESC'); $stmt->execute([$id]); $bookings=$stmt->fetchAll();
?>
<html><head><link rel="stylesheet" href="../css/all.min.css"><link rel="stylesheet" href="../css/bootstrap.min.css"><link rel="stylesheet" href="../css/style.css"><title>User Details - Furni</title></head><body><?php include '_admin_nav.php'; ?><section class="bg-main py-5"><div class="container py-4"><div class="card shadow border-0 rounded-4 mb-4"><div class="card-body"><h3>User Details</h3><p><strong>Username:</strong> <?php echo e($user['username']); ?></p><p><strong>Email:</strong> <?php echo e($user['email']); ?></p><p><strong>Role:</strong> <?php echo e($user['role']); ?></p><p><strong>Joined:</strong> <?php echo e($user['created_at']); ?></p></div></div><div class="card shadow border-0 rounded-4"><div class="card-body"><h3>Booking History</h3><div class="table-responsive"><table class="table table-striped"><thead class="table-dark"><tr><th>Car</th><th>Pickup</th><th>Return</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach($bookings as $b): ?><tr><td><?php echo e($b['car_name']); ?></td><td><?php echo e($b['pickup_date']); ?></td><td><?php echo e($b['return_date']); ?></td><td>$<?php echo number_format((float)$b['total_price'],2); ?></td><td><?php echo e($b['status']); ?></td></tr><?php endforeach; ?><?php if(!$bookings): ?><tr><td colspan="5" class="text-center">No bookings.</td></tr><?php endif; ?></tbody></table></div></div></div></div></section><script src="../js/bootstrap.bundle.min.js"></script></body></html>
